class JsonProtocolActions(object):
    """
    Enumerates available json actions that are possible to handle via UE control app.
    Names needs to be synchronized with the actions @app code
    """

    GET_CELL_INFO = "getCellInfo"
    IS_EMERGENCY_CALL_NUMBER = "isEmergencyCallNumber"
    MAKE_EMERGENCY_CALL = "makeEmergencyCall"
    IS_IN_CALL = "isInCall"
    GET_MOBILE_AVERAGE_THROUGHPUT = "getMobileAverageThroughput"
